function isEnabled(value) {
  if (value === true || value === 1) return true;
  const s = String(value ?? '').trim().toUpperCase();
  return s === 'TRUE' || s === 'YES' || s === '1';
}

const rows = $input.all().filter((item) => {
  const cat = String(item.json.category ?? '').trim().toLowerCase();
  if (!cat || cat === 'category') return false;
  return true;
});

const enabled = rows.filter((item) => isEnabled(item.json.enabled));

if (enabled.length === 0) {
  const debug = rows.map((item) => ({
    category: item.json.category,
    enabled: item.json.enabled,
    enabledType: typeof item.json.enabled,
    keys: Object.keys(item.json),
  }));
  throw new Error(
    `No enabled categories. Check Config tab column "enabled" = TRUE. Rows seen: ${JSON.stringify(debug)}`,
  );
}

return enabled;

const config = $('Loop Over Categories').item.json;
const files = $input.all()
  .map((i) => i.json)
  .filter((f) => f && f.id && f.name);

if (files.length === 0) {
  return [
    {
      json: {
        ...config,
        hasVideo: false,
      },
    },
  ];
}

files.sort(
  (a, b) => new Date(a.createdTime).getTime() - new Date(b.createdTime).getTime(),
);
const file = files[0];

return [
  {
    json: {
      ...config,
      hasVideo: true,
      fileId: file.id,
      fileName: file.name,
      mimeType: file.mimeType || 'video/mp4',
      createdTime: file.createdTime,
    },
  },
];

// Paste into n8n: "Gemini title + captions" (Code node)
// Run Once for All Items | JavaScript
//
// Pipeline: Google Drive → Pick oldest → Download video (MP4 binary)
//   → this node (Gemini API for title; pass-through same binary)
//   → parallel: Upload YouTube | IG branch | FB branch
//
// Key: GEMINI_API_KEY in docker/.env (restart compose after change).

const item = $input.first();
const meta = item.json;

let wc = {};
try {
  wc = $('Workflow constants').first()?.json || {};
} catch {
  /* Workflow constants node missing */
}

const preferredModel = (wc.gemini_model || 'gemini-3.5-flash-lite').trim();

let fromEnv = '';
try {
  if (typeof $env !== 'undefined' && $env.GEMINI_API_KEY) {
    fromEnv = String($env.GEMINI_API_KEY);
  }
} catch {
  /* n8n blocks $env unless N8N_BLOCK_ENV_ACCESS_IN_NODE=false — use Workflow constants */
}

const apiKey = String(fromEnv || wc.gemini_api_key || '').trim();

if (!apiKey) {
  throw new Error(
    'Gemini API key missing. Either: (1) Workflow constants → gemini_api_key, or (2) Docker env GEMINI_API_KEY + N8N_BLOCK_ENV_ACCESS_IN_NODE=false, then restart n8n.',
  );
}

async function geminiRequest(method, path, body) {
  const opts = {
    method,
    url: `https://generativelanguage.googleapis.com/v1beta/${path}`,
    headers: {
      'Content-Type': 'application/json',
      'x-goog-api-key': apiKey,
    },
    json: true,
    ignoreHttpStatusErrors: true,
  };
  if (body !== undefined) opts.body = body;
  return await this.helpers.httpRequest(opts);
}

const listResp = await geminiRequest.call(this, 'GET', 'models', undefined);
if (listResp?.error) {
  throw new Error(
    `Gemini list models failed: ${listResp.error.message || JSON.stringify(listResp.error)}. ` +
      'https://aistudio.google.com/apikey',
  );
}

const generateModels = (listResp.models || [])
  .filter((m) => (m.supportedGenerationMethods || []).includes('generateContent'))
  .map((m) => (m.name || '').replace(/^models\//, ''))
  .filter(Boolean);

if (generateModels.length === 0) {
  throw new Error('No generateContent models returned for this API key.');
}

function isRetryable(msg) {
  return /no longer available|not available to new users|not found|429|quota|RESOURCE_EXHAUSTED|rate limit|billing|depleted|invalid argument.*video|mime/i.test(
    String(msg || ''),
  );
}

function pickModels() {
  const order = [
    preferredModel,
    'gemini-3.5-flash-lite',
    'gemini-3.8-flash',
    'gemini-2.5-flash',
    'gemini-2.5-flash-lite',
    'gemini-2.5-flash-preview-05-20',
    'gemini-flash-latest',
    'gemini-flash-lite-latest',
  ];
  const picked = [];
  for (const id of order) {
    if (id && generateModels.includes(id) && !picked.includes(id)) picked.push(id);
  }
  for (const id of generateModels) {
    if (/flash/i.test(id) && !/tts|image|embedding|exp-/i.test(id) && !picked.includes(id)) {
      picked.push(id);
    }
  }
  if (!picked.length) picked.push(generateModels[0]);
  return picked;
}

function extractTitle(response) {
  const parts = response?.candidates?.[0]?.content?.parts || [];
  return parts
    .map((p) => (typeof p.text === 'string' ? p.text : ''))
    .join('')
    .replace(/[\n\r#"]+/g, ' ')
    .trim()
    .slice(0, 80);
}

/** Strip category/channel prefix if the model still adds it (e.g. "Balaji relaxes…"). */
function polishTitle(title, categoryLabel) {
  let t = String(title || '').trim();
  if (!t) return t;
  const labels = [
    categoryLabel,
    'Balaji',
    'Laya',
    'Balaji and Laya',
    'Balaji_and_Laya',
    'Friends',
  ]
    .filter(Boolean)
    .map((s) => String(s).trim())
    .filter((s) => s.length > 1);
  for (const label of labels) {
    const re = new RegExp(`^${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*[-–—:|]?\\s*`, 'i');
    t = t.replace(re, '').trim();
    const reMid = new RegExp(`\\b${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\b`, 'gi');
    t = t.replace(reMid, '').replace(/\s{2,}/g, ' ').trim();
  }
  return t.slice(0, 80);
}

const modelsToTry = pickModels();

const binaryKey = Object.keys(item.binary || {})[0];
if (!binaryKey) throw new Error('No video binary from Download video.');

const buffer = await this.helpers.getBinaryDataBuffer(0, binaryKey);
const maxBytes = 18 * 1024 * 1024;
if (buffer.length > maxBytes) {
  throw new Error(`Video too large (${(buffer.length / 1024 / 1024).toFixed(1)} MB). Max ~18 MB.`);
}

const base64 = buffer.toString('base64');
const mimeType = item.binary[binaryKey].mimeType || meta.mimeType || 'video/mp4';
const category = String(meta.category || 'shorts').trim();
const hashtags = meta.standard_hashtags || meta.standard_hashtag || '';

// Category (Balaji, Laya, …) is routing only — never in the public title.
const prompt = [
  'You write one short title for a calm, relaxing anime-style vertical short (cozy / unwind vibe).',
  'Watch the video. Describe what you see: who is there (e.g. a man, someone), what they do, place, mood, props.',
  'Use natural English with a relaxing tone. Include at least one calm word such as: relaxing, unwind, peaceful, quiet, cozy, serene, gentle, calm.',
  'If someone is resting or sitting peacefully, say it plainly (e.g. "A man relaxing under the stars with coffee", "Unwinding by the mountains at dusk").',
  'Vary wording each time — do not reuse the same sentence pattern.',
  'Return ONLY the title. Max 80 characters. No hashtags. No quotes.',
  'Do NOT use: filename; Animate, export, mp4;',
  `channel/category names (${category}, Balaji, Laya, Friends) unless written on-screen in the video.`,
].join(' ');

const bodyVideo = {
  contents: [
    {
      parts: [
        { inline_data: { mime_type: mimeType, data: base64 } },
        { text: prompt },
      ],
    },
  ],
  generationConfig: { temperature: 0.85, maxOutputTokens: 256 },
};

const bodyTextOnly = {
  contents: [
    {
      parts: [
        {
          text: `${prompt} (If video unavailable: invent a cozy relaxing scene title with calm wording — no channel names, not a filename.)`,
        },
      ],
    },
  ],
  generationConfig: { temperature: 0.85, maxOutputTokens: 256 },
};

const gemini_attempts = [];
let response;
let usedModel;
let titleSource = 'video';
let lastError = '';

for (const m of modelsToTry) {
  response = await geminiRequest.call(this, 'POST', `models/${m}:generateContent`, bodyVideo);
  const title = !response?.error && response?.candidates?.length ? extractTitle(response) : '';
  if (title) {
    usedModel = m;
    lastError = '';
    gemini_attempts.push({ step: 'video', model: m, ok: true });
    break;
  }
  lastError = response?.error?.message || 'empty or blocked response';
  gemini_attempts.push({ step: 'video', model: m, ok: false, error: lastError });
  if (!isRetryable(lastError)) break;
}

let ai_title = response && !response?.error ? extractTitle(response) : '';

if (!ai_title) {
  titleSource = 'text-only';
  for (const m of modelsToTry) {
    response = await geminiRequest.call(this, 'POST', `models/${m}:generateContent`, bodyTextOnly);
    ai_title = !response?.error && response?.candidates?.length ? extractTitle(response) : '';
    if (ai_title) {
      usedModel = `${m} (text-only fallback)`;
      gemini_attempts.push({ step: 'text-only', model: m, ok: true });
      break;
    }
    lastError = response?.error?.message || 'empty response';
    gemini_attempts.push({ step: 'text-only', model: m, ok: false, error: lastError });
    if (!isRetryable(lastError)) break;
  }
}

if (!ai_title) {
  throw new Error(
    `Gemini could not produce a title. Last error: ${response?.error?.message || lastError}. ` +
      `Tried: ${modelsToTry.slice(0, 6).join(', ')}. Attempts: ${JSON.stringify(gemini_attempts)}`,
  );
}

ai_title = polishTitle(ai_title, category);
if (!ai_title) {
  throw new Error('Gemini title empty after polish. Check prompt or video input.');
}

// YouTube: AI title only; description from Config / Workflow constants (not Gemini).
// IG + FB: title + hashtags from Config.
const socialCaption = hashtags ? `${ai_title}\n\n${hashtags}`.trim() : ai_title;
const youtubeDescription = String(
  meta.youtube_description ||
    meta.default_youtube_description ||
    wc.youtube_default_description ||
    '',
).trim();

const driveFileName = String(meta.fileName || meta.name || '').trim();
const binaryMeta = item.binary?.[binaryKey] || {};
const binaryFileName = String(
  binaryMeta.fileName || binaryMeta.file_name || driveFileName || 'video.mp4',
).trim();
const videoBytes = buffer.length;

// One stable MP4 attachment for YouTube + IG + FB (avoids parallel reads on filesystem refs).
const videoBinary = await this.helpers.prepareBinaryData(
  buffer,
  binaryFileName,
  mimeType,
);

return [
  {
    json: {
      ...meta,
      drive_video_file_name: driveFileName,
      binary_video_file_name: binaryFileName,
      video_byte_size: videoBytes,
      ai_title,
      gemini_model_used: usedModel,
      gemini_title_source: titleSource,
      gemini_attempts,
      youtubeTitle: ai_title.slice(0, 100),
      youtubeDescription,
      igCaption: socialCaption,
      fbCaption: socialCaption,
    },
    binary: {
      data: videoBinary,
    },
  },
];

// Paste into n8n node: "Collect post links" (Code node)

function nodeJson(nodeName) {
  try {
    return $(nodeName).first()?.json || {};
  } catch {
    return {};
  }
}

const base = $('Gemini title + captions').first().json;
const yt = nodeJson('Upload YouTube');
const igCreate = nodeJson('IG Reels 1 Create container');
const igPublish = nodeJson('Instagram Reels (Graph)');
const igMeta = nodeJson('IG Fetch post link');
const igRupload = nodeJson('IG Reels 3 Rupload');
const fbStart = nodeJson('FB Reels 1 Start');
const fbUpload = nodeJson('FB Reels 3 Upload video');
const fbFinish = nodeJson('FB Reels 4 Finish');
const fbMeta = nodeJson('FB Fetch post link');

function youtubeVideoId(data) {
  if (!data || data.error) return '';
  return (
    data.id ||
    data.videoId ||
    data.uploadId ||
    data?.snippet?.resourceId?.videoId ||
    data?.snippet?.id ||
    ''
  );
}

function errText(data) {
  if (!data) return 'no response';
  if (typeof data.error === 'string') return data.error;
  if (data.error?.message) return data.error.message;
  if (data.message) return data.message;
  if (data.errorDescription) return data.errorDescription;
  if (data.description) return data.description;
  return '';
}

function hasGraphError(data) {
  if (!data || typeof data !== 'object') return true;
  if (data.error) return true;
  if (data.status === 'failed' || data.status === 'error') return true;
  return false;
}

function metaUploadOk(data) {
  if (hasGraphError(data)) return false;
  if (data.success === true) return true;
  if (data.h) return true;
  if (typeof data.start_offset === 'string' && data.start_offset !== '0') return true;
  return false;
}

function fbPublishOk(finish) {
  if (hasGraphError(finish)) return false;
  return finish.success === true || Boolean(finish.post_id || finish.id);
}

function youtubeNote(data) {
  const t = errText(data);
  if (/uploadLimitExceeded|exceeded.*upload|daily.*limit|quota/i.test(t)) {
    return 'YouTube skipped: daily upload limit reached (resets ~midnight US Pacific).';
  }
  return `YouTube failed: ${t || 'no video id'}`;
}

/** Graph often returns permalink_url as /reel/123/ — Sheets need a full URL. */
function normalizeFacebookLink(raw) {
  let s = String(raw || '').trim();
  if (!s) return '';
  if (/^https?:\/\//i.test(s)) return s.replace(/\/+$/, '') || s;
  if (s.startsWith('//')) return `https:${s}`.replace(/\/+$/, '');
  if (s.startsWith('/')) {
    const path = s.replace(/\/+$/, '');
    return `https://www.facebook.com${path}`;
  }
  if (/^\d+$/.test(s)) return `https://www.facebook.com/reel/${s}`;
  return s;
}

const vid = youtubeVideoId(yt);
const youtube_link = vid ? `https://www.youtube.com/shorts/${vid}` : '';

const igContainerOk = !hasGraphError(igCreate) && Boolean(igCreate?.id);
const igPublishedOk = !hasGraphError(igPublish) && Boolean(igPublish?.id);
const igPermalink = !hasGraphError(igMeta) && igMeta?.permalink ? String(igMeta.permalink) : '';

const instagram_link =
  igContainerOk && igPublishedOk && igPermalink ? igPermalink : '';

let facebook_link = '';
if (
  metaUploadOk(fbUpload) &&
  fbPublishOk(fbFinish) &&
  !hasGraphError(fbMeta) &&
  fbMeta?.permalink_url
) {
  facebook_link = normalizeFacebookLink(fbMeta.permalink_url);
}

const platformNotes = [];
if (!youtube_link) {
  platformNotes.push(youtubeNote(yt));
}
if (!instagram_link) {
  const containerId = igCreate?.id || igPublish?.id;
  const igId = containerId ? ` (container ${containerId})` : '';
  const igErr =
    errText(igCreate) ||
    errText(igRupload) ||
    errText(igPublish) ||
    errText(igMeta) ||
    (igContainerOk && igPublishedOk ? 'no permalink from IG Fetch post link' : 'no permalink');
  platformNotes.push(`Instagram failed: ${igErr}${igId}`);
}
if (!facebook_link) {
  const fbVid = fbStart?.video_id ? ` (video id ${fbStart.video_id})` : '';
  platformNotes.push(
    `Facebook failed: ${errText(fbUpload) || errText(fbFinish) || errText(fbMeta) || errText(fbStart) || 'no permalink'}${fbVid}`,
  );
}

const okCount = [youtube_link, instagram_link, facebook_link].filter(Boolean).length;
let status = 'posted';
if (okCount === 0) status = 'failed';
else if (okCount < 3) status = 'partial';

let notes = platformNotes.join(' | ');
if (base.gemini_skip_reason) {
  notes = [base.gemini_skip_reason, notes].filter(Boolean).join(' | ');
}

const doneId = String(base.drive_done_folder_id || '');
const publishedSomewhere = Boolean(youtube_link || instagram_link || facebook_link);
const moveToDone =
  Boolean(base.fileId) &&
  base.hasVideo !== false &&
  Boolean(doneId) &&
  !doneId.includes('PASTE') &&
  publishedSomewhere;

return [
  {
    json: {
      ...base,
      youtube_link,
      instagram_link,
      facebook_link,
      status,
      notes,
      moveToDone,
    },
  },
];

// Node: IG Reels 2 Prepare upload (after IG Merge video + container)
// Full MP4 bytes for rupload (same pattern as FB Prepare).

const item = $input.first();
const j = item.json || {};

const containerId = j.id || j.ig_container_id;
const containerUri = j.uri;
if (!containerId && !containerUri) {
  throw new Error(
    'Missing IG container id/uri after merge. json=' + JSON.stringify(j).slice(0, 400),
  );
}

const gem = $('Gemini title + captions').first();
if (!gem?.binary?.data && !Object.keys(gem.binary || {}).length) {
  throw new Error('Missing video binary on Gemini title + captions.');
}

const binaryKey = gem.binary?.data ? 'data' : Object.keys(gem.binary)[0];
const srcMeta = gem.binary[binaryKey] || {};

const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  binaryKey,
  $('Gemini title + captions').all(),
);
const fileSize = buffer?.length || Number(gem.json?.video_byte_size) || 0;
if (!(fileSize > 0)) {
  throw new Error('Video buffer empty on Gemini output.');
}

const fileName =
  srcMeta.fileName ||
  srcMeta.file_name ||
  gem.json?.binary_video_file_name ||
  gem.json?.drive_video_file_name ||
  'video.mp4';
const mimeType = srcMeta.mimeType || srcMeta.mime_type || 'video/mp4';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

return [
  {
    json: {
      ...j,
      id: containerId || j.id,
      rupload_url:
        containerUri ||
        j.rupload_url ||
        `https://rupload.facebook.com/ig-api-upload/v23.0/${containerId}`,
      file_size: String(fileSize),
      ig_container_id: containerId,
    },
    binary: {
      data: binaryData,
    },
  },
];

// Node: FB Reels 2 Prepare upload (after FB Reels 1 Start)
// Fresh binary attachment for rupload (pass-through metadata alone corrupts uploads).

const start = $('FB Reels 1 Start').first()?.json || {};
const item = $input.first();
const j = { ...start, ...(item.json || {}) };

const videoId = j.video_id || j.videoId;
const uploadUrl = j.upload_url || j.uploadUrl;
if (j.error) {
  throw new Error('FB Start failed: ' + JSON.stringify(j.error).slice(0, 500));
}
if (!videoId) {
  throw new Error('Missing video_id from FB Start. json=' + JSON.stringify(j).slice(0, 400));
}

const gem = $('Gemini title + captions').first();
if (!gem?.binary?.data && !Object.keys(gem.binary || {}).length) {
  throw new Error('Missing video binary on Gemini title + captions.');
}

const binaryKey = gem.binary?.data ? 'data' : Object.keys(gem.binary)[0];
const srcMeta = gem.binary[binaryKey] || {};

const buffer = await this.helpers.getBinaryDataBuffer(
  0,
  binaryKey,
  $('Gemini title + captions').all(),
);
const fileSize = buffer?.length || Number(gem.json?.video_byte_size) || 0;
if (!(fileSize > 0)) {
  throw new Error('Video buffer empty on Gemini output.');
}

const fileName =
  srcMeta.fileName ||
  srcMeta.file_name ||
  gem.json?.binary_video_file_name ||
  gem.json?.drive_video_file_name ||
  'video.mp4';
const mimeType = srcMeta.mimeType || srcMeta.mime_type || 'video/mp4';

const binaryData = await this.helpers.prepareBinaryData(buffer, fileName, mimeType);

const resolvedUploadUrl =
  uploadUrl || `https://rupload.facebook.com/video-upload/v23.0/${videoId}`;

return [
  {
    json: {
      video_id: videoId,
      upload_url: resolvedUploadUrl,
      file_size: String(fileSize),
    },
    binary: {
      data: binaryData,
    },
  },
];

// Node: FB Resolve page token (after FB Get page token)

const pageId = String(
  $('Workflow constants').first()?.json?.meta_fb_page_id ||
    $env.META_FB_PAGE_ID ||
    '',
).trim();

if (!pageId) throw new Error('Set meta_fb_page_id in Workflow constants.');

const raw = $input.first()?.json || {};

if (raw.error?.code === 104 || /access token is required/i.test(String(raw.error?.message || ''))) {
  throw new Error(
    'Facebook Graph credential sent no access token (Graph #104). ' +
      'In n8n: Credentials → Facebook Graph account → Reconnect (Balaji1 App ID/Secret). ' +
      'Balaji1 → Facebook Login → add redirect http://localhost:5678/rest/oauth2-credential/callback . ' +
      'On node FB Get page token, re-select the same credential as Instagram nodes.',
  );
}

function pickPagePayload(body) {
  if (!body || typeof body !== 'object') return null;
  if (body.error) return { error: body.error };
  // Direct GET /{page-id}?fields=access_token,...
  if (body.access_token && String(body.id || pageId) === pageId) return body;
  if (body.access_token && !body.data) return { ...body, id: body.id || pageId };
  // GET /me/accounts
  const list = body.data || body.accounts?.data;
  if (Array.isArray(list)) {
    return list.find((p) => String(p.id) === pageId) || null;
  }
  return null;
}

const page = pickPagePayload(raw);

if (page?.error) {
  const msg = page.error.message || JSON.stringify(page.error);
  throw new Error(
    `Graph error loading Page token: ${msg}. ` +
      'Add scopes pages_show_list + pages_manage_posts, reconnect Facebook credential, select Page TheSolitarywolf.',
  );
}

if (!page?.access_token) {
  throw new Error(
    `No Page access_token for Page id ${pageId}. Response keys: ${JSON.stringify(Object.keys(raw))}. ` +
      'Raw (trimmed): ' +
      JSON.stringify(raw).slice(0, 800) +
      '. Fix: Meta app → pages_manage_posts → n8n credential Custom Scopes → reconnect. See META-FB-REELS-PERMISSION-FIX.md',
  );
}

return [
  {
    json: {
      page_id: String(page.id || pageId),
      page_name: page.name || '',
      page_access_token: page.access_token,
    },
  },
];

// Node: IG Build video URL (after Gemini)
// Meta pulls the MP4 from this URL — no rupload. Drive file/folder must allow link access.

const gem = $('Gemini title + captions').first()?.json || {};
const fileId = String(gem.fileId || '').trim();
if (!fileId) {
  throw new Error('Missing fileId for IG video_url. Check Pick oldest / Download video.');
}

let wc = {};
try {
  wc = $('Workflow constants').first()?.json || {};
} catch {
  /* optional */
}

const prefix = String(wc.ig_video_url_prefix || '').trim();
const fileName = String(gem.fileName || gem.drive_video_file_name || 'video.mp4').trim();

let ig_video_url;
if (prefix) {
  ig_video_url = prefix.endsWith('/')
    ? prefix + encodeURIComponent(fileName)
    : `${prefix}${encodeURIComponent(fileName)}`;
} else {
  ig_video_url = `https://drive.google.com/uc?export=download&confirm=t&id=${fileId}`;
}

return [
  {
    json: {
      ...gem,
      ig_video_url,
      ig_video_url_hint:
        prefix
          ? 'Using ig_video_url_prefix from Workflow constants.'
          : 'Using Google Drive direct link — share this file (or folder) as Anyone with the link can view.',
    },
  },
];
